import { describe, expect, it } from 'vitest';
import { CORPUS_OPTION_SETS, SHIPPED_OPTIONS, buildSettingsDat, optionLabel, readSettingsDat } from './settings';

// The first lines of the settings.dat that ships with EASy68K v5.16.1 (the assembler options and
// the editor's tab settings; the colour lines that follow do not matter here).
const SHIPPED_TEXT = [
  '$Settings for EASy68K Editor/Assembler v5.15.04  DO NOT EDIT THIS FILE!!!!',
  '1$generate list',
  '1$generate s-record',
  '0$save then assemble',
  '1$show warnings',
  '1$cross reference',
  '0$macros expanded',
  '0$structured expand',
  '0$constants expand',
  'Courier New$font name',
  '10$font size',
  '1$tab type',
  '4$fixed tab size',
  '0$maximized edit',
  '1$auto indent',
  '0$real tabs',
  '1$assemble bit field',
  '106$main top',
  '',
].join('\r\n');
const SHIPPED = Uint8Array.from(Buffer.from(SHIPPED_TEXT, 'latin1'));
const text = (bytes: Uint8Array): string[] => Buffer.from(bytes).toString('latin1').split('\r\n');

describe('buildSettingsDat', () => {
  it('returns the shipped file for the shipped options', () => {
    expect(buildSettingsDat(SHIPPED, {})).toEqual(SHIPPED);
    expect(buildSettingsDat(SHIPPED, SHIPPED_OPTIONS)).toEqual(SHIPPED);
    expect(readSettingsDat(SHIPPED)).toEqual(SHIPPED_OPTIONS);
  });

  it('changes only the value of the lines it is asked to change', () => {
    const lines = text(buildSettingsDat(SHIPPED, CORPUS_OPTION_SETS.expand));
    const before = SHIPPED_TEXT.split('\r\n');
    const changed = lines.flatMap((line, index) => (line === before[index] ? [] : [line]));
    expect(changed).toEqual(['1$macros expanded', '1$structured expand', '1$constants expand']);
    expect(lines).toHaveLength(before.length);
  });

  it('writes every option and reads it back', () => {
    const options = {
      generateListing: false,
      generateSRecord: false,
      showWarnings: false,
      crossReference: false,
      macrosExpanded: true,
      structuredExpanded: true,
      constantsExpanded: true,
      tabType: 0,
      tabSize: 20,
      bitFieldInstructions: false,
    } as const;
    const built = buildSettingsDat(SHIPPED, options);
    expect(readSettingsDat(built)).toEqual(options);
    expect(text(built)).toContain('0$tab type');
    expect(text(built)).toContain('20$fixed tab size');
    // The lines the editor reads by position are all still there, in order.
    expect(text(built).map((line) => line.slice(line.indexOf('$')))).toEqual(
      SHIPPED_TEXT.split('\r\n').map((line) => line.slice(line.indexOf('$'))),
    );
  });

  it('refuses values the original cannot hold and files without the line', () => {
    expect(() => buildSettingsDat(SHIPPED, { tabSize: 100 })).toThrow(RangeError);
    expect(() => buildSettingsDat(SHIPPED, { tabSize: 2.5 })).toThrow(RangeError);
    expect(() => buildSettingsDat(SHIPPED, { tabType: 2 as 0 })).toThrow(RangeError);
    expect(() => buildSettingsDat(SHIPPED, { showWarnings: 1 as unknown as boolean })).toThrow(TypeError);
    expect(() => buildSettingsDat(SHIPPED, { unknown: true } as object)).toThrow(/unknown assembler option/);
    const noBitField = Uint8Array.from(Buffer.from(SHIPPED_TEXT.replace('1$assemble bit field\r\n', ''), 'latin1'));
    expect(() => buildSettingsDat(noBitField, { bitFieldInstructions: false })).toThrow(
      /no "\$assemble bit field" line/,
    );
  });
});

describe('optionLabel', () => {
  it('names the two corpus option sets', () => {
    expect(optionLabel(CORPUS_OPTION_SETS.default)).toBe('default');
    expect(optionLabel(CORPUS_OPTION_SETS.expand)).toBe('mex+sex+cex');
  });

  it('names only what differs from a fresh installation, in a fixed order', () => {
    expect(optionLabel({ bitFieldInstructions: true, showWarnings: true })).toBe('default');
    expect(optionLabel({ bitFieldInstructions: false, crossReference: false, generateListing: false })).toBe(
      'nolist+nocre+nobit',
    );
    expect(optionLabel({ tabType: 0 })).toBe('tab-assembly');
    expect(optionLabel({ tabType: 1, tabSize: 8 })).toBe('tab-fixed-8');
    expect(optionLabel({ tabType: 1, tabSize: 4 })).toBe('default');
  });

  it('gives different labels to different option sets', () => {
    const flags = [
      'showWarnings',
      'crossReference',
      'macrosExpanded',
      'structuredExpanded',
      'constantsExpanded',
      'bitFieldInstructions',
    ] as const;
    const labels = new Set<string>();
    for (let mask = 0; mask < 64; mask++) {
      labels.add(optionLabel(Object.fromEntries(flags.map((flag, bit) => [flag, Boolean(mask & (1 << bit))]))));
    }
    expect(labels.size).toBe(64);
  });
});
